/bin/bash -lc 'GOAI_WORKSPACE="$GOAI_WORKSPACE" GOAI_HTTP_MIN_INTERVAL=0.2 .venv/bin/python - <<'"'PY'
import os, json, logging
from concurrent.futures import ThreadPoolExecutor, as_completed
from server.core import bibtex as bib
from server.refcheck_server import _verify_fields
logging.getLogger().setLevel(logging.WARNING)
base=os.environ['GOAI_WORKSPACE']; bib_path=os.path.join(base,'library','references.bib'); out_dir=os.path.join(base,'state')
entries=bib.parse_bibtex(open(bib_path,encoding='utf-8').read())
def check(e):
 try:r=_verify_fields(e['fields'])
 except Exception as exc:r={'verdict':'ERROR','reason':f'{type(exc).__name__}: {exc}'}
 return {'key':e['key'],**r}
results=[None]*len(entries)
with ThreadPoolExecutor(max_workers=12) as ex:
 futs={ex.submit(check,e):i for i,e in enumerate(entries)}; done=0
 for fut in as_completed(futs):
  results[futs[fut]]=fut.result(); done+=1
  if done%50==0: print(f'checked {done}/{len(entries)}',flush=True)
counts={k:0 for k in ('PASS','FIX','MISMATCH','UNVERIFIED','ERROR')}
for r in results:counts[r.get('verdict','ERROR')]=counts.get(r.get('verdict','ERROR'),0)+1
gate='PASS' if counts['MISMATCH']==0 and counts['UNVERIFIED']==0 and counts['ERROR']==0 else 'FAIL'
audit={'audit_skill':'goai-refcheck','bib_file':bib_path,'total':len(entries),'counts':counts,'gate':gate,'per_entry':results}
os.makedirs(out_dir,exist_ok=True)
json_path=os.path.join(out_dir,'CITATION_AUDIT.json'); md_path=os.path.join(out_dir,'CITATION_AUDIT.md')
with open(json_path,'w',encoding='utf-8') as f:json.dump(audit,f,ensure_ascii=False,indent=2)
lines=[f'# 引用核查报告\\n\\n- bib: "'`{bib_path}`'"\\n- 条目: {len(entries)}',f'- 裁决分布: {counts}\\n- 闸门: **{gate}**\\n']
for r in results:
 if r.get('verdict')=='PASS':continue
 lines.append(f\"## {r.get('verdict')}: "'`{r.get('"'key')}"'`")
 for i in r.get('"'issues',[]):lines.append(f\"- [{i.get('axis','?')}] {i.get('detail',i.get('type'))}\")
 if r.get('reason'):lines.append(f\"- {r['reason']}\")
 if r.get('suggested_bibtex'):lines.append('\\n"'```bibtex'"\\n'+r['suggested_bibtex']+'\\n"'```'"')
 lines.append('')
with open(md_path,'w',encoding='utf-8') as f:f.write('\\n'.join(lines))
print(json.dumps({'total':len(entries),'counts':counts,'gate':gate,'report_json':json_path,'report_md':md_path},ensure_ascii=False),flush=True)
PY"
